import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.*;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import java.sql.*;
import java.util.*;
import java.util.concurrent.Executors;
import java.util.concurrent.ConcurrentHashMap;
import java.time.Instant;

/** Small, dependency-light Java 17 API equivalent to server.js. */
public class server {
  static final ObjectMapper JSON = new ObjectMapper();
  static final String DB = "jdbc:sqlite:database-java.db";
  static final int PORT = Integer.parseInt(System.getenv().getOrDefault("PORT", "3001"));
  static final Map<String,Integer> ADMIN_TOKENS = new ConcurrentHashMap<>();

  public static void main(String[] args) throws Exception {
    Class.forName("org.sqlite.JDBC");
    try (Connection c = db()) {
      c.createStatement().executeUpdate("PRAGMA foreign_keys = ON");
      c.createStatement().executeUpdate("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'student', created_at TEXT DEFAULT CURRENT_TIMESTAMP)");
      addColumnIfMissing(c, "users", "admin_id", "TEXT");
      c.createStatement().executeUpdate("CREATE TABLE IF NOT EXISTS courses (id INTEGER PRIMARY KEY AUTOINCREMENT, course_code TEXT NOT NULL UNIQUE, course_name TEXT NOT NULL, lecturer_id INTEGER NOT NULL, FOREIGN KEY(lecturer_id) REFERENCES users(id))");
      c.createStatement().executeUpdate("CREATE TABLE IF NOT EXISTS attendance_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL, \"date\" TEXT NOT NULL, \"time\" TEXT NOT NULL, token TEXT NOT NULL UNIQUE, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE)");
      c.createStatement().executeUpdate("CREATE TABLE IF NOT EXISTS attendance (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('Present','Absent','Late')), recorded_at TEXT DEFAULT CURRENT_TIMESTAMP, session_id INTEGER, selfie_path TEXT, location_verified INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(session_id) REFERENCES attendance_sessions(id) ON DELETE CASCADE)");
      addColumnIfMissing(c, "attendance", "session_id", "INTEGER"); addColumnIfMissing(c, "attendance", "selfie_path", "TEXT"); addColumnIfMissing(c, "attendance", "location_verified", "INTEGER NOT NULL DEFAULT 0");
      c.createStatement().executeUpdate("CREATE UNIQUE INDEX IF NOT EXISTS idx_attendance_user_session ON attendance(user_id, session_id) WHERE session_id IS NOT NULL");
    }
    HttpServer api = HttpServer.create(new InetSocketAddress(PORT), 0);
    api.createContext("/health", e -> respond(e, 200, Map.of("status", "ok")));
    api.createContext("/register", e -> handle(e, "register"));
    api.createContext("/login", e -> handle(e, "login"));
    api.createContext("/admin/register", e -> handle(e, "admin-register"));
    api.createContext("/admin/login", e -> handle(e, "admin-login"));
    api.createContext("/attendance", e -> handle(e, "attendance"));
    api.createContext("/courses", e -> handle(e, "courses"));
    api.createContext("/lecturer/overview", e -> handle(e, "lecturer-overview"));
    api.createContext("/lecturer/create-course", e -> handle(e, "create-course"));
    api.createContext("/lecturer/create-session", e -> handle(e, "create-session"));
    api.createContext("/attendance/scan", e -> handle(e, "scan"));
    api.createContext("/admin/overview", e -> handle(e, "admin-overview"));
    api.setExecutor(Executors.newFixedThreadPool(8)); api.start();
    System.out.println("SmartAttend Java API running at http://localhost:" + PORT);
  }

  static Connection db() throws SQLException { return DriverManager.getConnection(DB); }
  static void handle(HttpExchange e, String route) throws IOException {
    try {
      if ("OPTIONS".equalsIgnoreCase(e.getRequestMethod())) { e.getResponseHeaders().set("Access-Control-Allow-Methods", "GET, POST, OPTIONS"); e.getResponseHeaders().set("Access-Control-Allow-Headers", "Content-Type, Authorization"); respond(e, 204, Map.of()); return; }
      boolean getRoute = "GET".equalsIgnoreCase(e.getRequestMethod()) && (route.equals("courses") || route.equals("admin-overview") || route.equals("lecturer-overview"));
      if (!"POST".equalsIgnoreCase(e.getRequestMethod()) && !getRoute) { respond(e, 405, Map.of("error", getRoute ? "GET is required." : "POST is required.")); return; }
      JsonNode b = "POST".equalsIgnoreCase(e.getRequestMethod()) ? JSON.readTree(e.getRequestBody()) : null;
      if (route.equals("register")) register(e, b); else if (route.equals("login")) login(e, b); else if (route.equals("admin-register")) adminRegister(e, b); else if (route.equals("admin-login")) adminLogin(e, b); else if (route.equals("attendance")) attendance(e, b); else if (route.equals("courses")) courses(e); else if (route.equals("admin-overview")) { if (!requireAdmin(e)) return; adminOverview(e); } else if (route.equals("lecturer-overview")) lecturerOverview(e); else if (route.equals("create-course")) createCourse(e, b); else if (route.equals("create-session")) createSession(e, b); else scanAttendance(e, b);
    } catch (Exception ex) { ex.printStackTrace(); respond(e, 500, Map.of("error", "Unexpected server error.")); }
  }
  static String text(JsonNode n, String key) { return n != null && n.has(key) ? n.get(key).asText().trim() : ""; }
  static void register(HttpExchange e, JsonNode b) throws Exception {
    String username=text(b,"username"), email=text(b,"email").toLowerCase(), password=text(b,"password"), role=text(b,"role").toLowerCase(); if(role.isBlank()) role="student";
    if(username.length()<2 || username.length()>80 || !email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$") || password.length()<8 || password.length()>128 || !(role.equals("student")||role.equals("lecturer"))) { respond(e,400,Map.of("error","Invalid username, email, password, or role.")); return; }
    try(Connection c=db(); PreparedStatement p=c.prepareStatement("INSERT INTO users(username,email,password,role) VALUES(?,?,?,?)", Statement.RETURN_GENERATED_KEYS)) { p.setString(1,username); p.setString(2,email); p.setString(3,hash(password)); p.setString(4,role); p.executeUpdate(); try(ResultSet k=p.getGeneratedKeys()){ k.next(); respond(e,201,Map.of("message","User registered successfully.","user",user(k.getInt(1),username,email,role))); } }
    catch(SQLException x) { respond(e,x.getErrorCode()==19?409:500,Map.of("error",x.getErrorCode()==19?"That email is already registered.":"Could not create the account.")); }
  }
  static void login(HttpExchange e, JsonNode b) throws Exception { String email=text(b,"email").toLowerCase(), password=text(b,"password"); try(Connection c=db(); PreparedStatement p=c.prepareStatement("SELECT id,username,email,password,role FROM users WHERE email=?")){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(!r.next()||!verify(password,r.getString("password"))){respond(e,401,Map.of("error","Invalid email or password."));return;}respond(e,200,Map.of("message","Login successful.","user",user(r.getInt("id"),r.getString("username"),r.getString("email"),r.getString("role"))));}}}
  static void attendance(HttpExchange e, JsonNode b) throws Exception { int id=b.has("user_id")?b.get("user_id").asInt(-1):-1; String status=text(b,"status"); if(id<1||!(status.equals("Present")||status.equals("Absent")||status.equals("Late"))){respond(e,400,Map.of("error","Invalid user_id or status."));return;}try(Connection c=db()){try(PreparedStatement q=c.prepareStatement("SELECT id FROM users WHERE id=?")){q.setInt(1,id);if(!q.executeQuery().next()){respond(e,404,Map.of("error","User not found."));return;}}try(PreparedStatement p=c.prepareStatement("INSERT INTO attendance(user_id,status) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,id);p.setString(2,status);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();respond(e,201,Map.of("message","Attendance recorded.","attendanceId",k.getInt(1),"user_id",id,"status",status));}}}}
  static void courses(HttpExchange e) throws Exception { if(!"GET".equalsIgnoreCase(e.getRequestMethod())) { respond(e,405,Map.of("error","GET is required.")); return; } List<Map<String,Object>> rows=new ArrayList<>(); try(Connection c=db(); PreparedStatement p=c.prepareStatement("SELECT id,course_code,course_name,lecturer_id FROM courses ORDER BY course_code"); ResultSet r=p.executeQuery()){while(r.next()) rows.add(Map.of("id",r.getInt("id"),"course_code",r.getString("course_code"),"course_name",r.getString("course_name"),"lecturer_id",r.getInt("lecturer_id")));} respond(e,200,rows); }
  static void adminRegister(HttpExchange e, JsonNode b)throws Exception{String name=text(b,"name"),email=text(b,"email").toLowerCase(),adminId=text(b,"admin_id"),password=text(b,"password");if(name.length()<2||email.isBlank()||adminId.length()<2||password.length()<8){respond(e,400,Map.of("error","Name, email, administrator ID, and an 8-character password are required."));return;}try(Connection c=db();PreparedStatement p=c.prepareStatement("INSERT INTO users(username,email,password,role,admin_id) VALUES(?,?,?,'admin',?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,email);p.setString(3,hash(password));p.setString(4,adminId);p.executeUpdate();respond(e,201,Map.of("message","Administrator account created."));}catch(SQLException x){respond(e,x.getErrorCode()==19?409:500,Map.of("error",x.getErrorCode()==19?"Email or administrator ID already exists.":"Could not create administrator account."));}}
  static void adminLogin(HttpExchange e, JsonNode b)throws Exception{String email=text(b,"email").toLowerCase(),password=text(b,"password");try(Connection c=db();PreparedStatement p=c.prepareStatement("SELECT id,username,email,password,admin_id FROM users WHERE email=? AND role='admin'")){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(!r.next()||!verify(password,r.getString("password"))){respond(e,401,Map.of("error","Invalid administrator email or password."));return;}String token=UUID.randomUUID().toString();ADMIN_TOKENS.put(token,r.getInt("id"));respond(e,200,Map.of("message","Administrator login successful.","token",token,"user",Map.of("id",r.getInt("id"),"username",r.getString("username"),"email",r.getString("email"),"admin_id",r.getString("admin_id"))));}}}
  static boolean requireAdmin(HttpExchange e)throws IOException{String header=e.getRequestHeaders().getFirst("Authorization");String token=header!=null&&header.startsWith("Bearer ")?header.substring(7).trim():"";if(token.isBlank()||!ADMIN_TOKENS.containsKey(token)){respond(e,401,Map.of("error","Administrator authentication is required."));return false;}return true;}
  static void lecturerOverview(HttpExchange e) throws Exception { String query=e.getRequestURI().getQuery()==null?"":e.getRequestURI().getQuery(); int lecturerId=-1; for(String part:query.split("&")){String[] pair=part.split("=",2);if(pair.length==2&&pair[0].equals("lecturer_id"))try{lecturerId=Integer.parseInt(pair[1]);}catch(NumberFormatException ignored){}} if(lecturerId<1){respond(e,400,Map.of("error","lecturer_id is required."));return;} Map<String,Object> out=new LinkedHashMap<>(); List<Map<String,Object>> courseRows=new ArrayList<>(),sessionRows=new ArrayList<>(),attendanceRows=new ArrayList<>(); try(Connection c=db()){try(PreparedStatement p=c.prepareStatement("SELECT id,course_code,course_name,lecturer_id FROM courses WHERE lecturer_id=? ORDER BY course_code")){p.setInt(1,lecturerId);try(ResultSet r=p.executeQuery()){while(r.next())courseRows.add(Map.of("id",r.getInt("id"),"course_code",r.getString("course_code"),"course_name",r.getString("course_name"),"lecturer_id",r.getInt("lecturer_id")));}} try(PreparedStatement p=c.prepareStatement("SELECT s.id,s.course_id,c.course_code,c.course_name,s.\"date\",s.\"time\",s.token FROM attendance_sessions s JOIN courses c ON c.id=s.course_id WHERE c.lecturer_id=? ORDER BY s.id DESC")){p.setInt(1,lecturerId);try(ResultSet r=p.executeQuery()){while(r.next())sessionRows.add(Map.of("id",r.getInt("id"),"course_id",r.getInt("course_id"),"course_code",r.getString("course_code"),"course_name",r.getString("course_name"),"date",r.getString("date"),"time",r.getString("time"),"token",r.getString("token")));}} try(PreparedStatement p=c.prepareStatement("SELECT a.id,a.status,a.recorded_at,u.username,c.course_code,c.course_name,s.\"date\",s.\"time\" FROM attendance a JOIN users u ON u.id=a.user_id JOIN attendance_sessions s ON s.id=a.session_id JOIN courses c ON c.id=s.course_id WHERE c.lecturer_id=? ORDER BY a.id DESC")){p.setInt(1,lecturerId);try(ResultSet r=p.executeQuery()){while(r.next())attendanceRows.add(Map.of("id",r.getInt("id"),"status",r.getString("status"),"recorded_at",r.getString("recorded_at"),"username",r.getString("username"),"course_code",r.getString("course_code"),"course_name",r.getString("course_name"),"date",r.getString("date"),"time",r.getString("time")));}}} out.put("courses",courseRows);out.put("sessions",sessionRows);out.put("attendance",attendanceRows);out.put("attendanceCount",attendanceRows.size());respond(e,200,out); }
  static void adminOverview(HttpExchange e) throws Exception { Map<String,Object> out=new LinkedHashMap<>(); List<Map<String,Object>> users=new ArrayList<>(), activity=new ArrayList<>(); try(Connection c=db()){try(PreparedStatement p=c.prepareStatement("SELECT id,username,email,role,created_at FROM users ORDER BY id DESC");ResultSet r=p.executeQuery()){while(r.next())users.add(Map.of("id",r.getInt("id"),"username",r.getString("username"),"email",r.getString("email"),"role",r.getString("role"),"created_at",r.getString("created_at")));}try(PreparedStatement p=c.prepareStatement("SELECT a.id,a.user_id,u.username,a.status,a.session_id,a.selfie_path,a.location_verified,a.recorded_at,c.course_code,c.course_name,s.\"date\",s.\"time\" FROM attendance a JOIN users u ON u.id=a.user_id LEFT JOIN attendance_sessions s ON s.id=a.session_id LEFT JOIN courses c ON c.id=s.course_id ORDER BY a.id DESC LIMIT 50");ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> item=new LinkedHashMap<>(); item.put("id",r.getInt("id")); item.put("user_id",r.getInt("user_id")); item.put("username",r.getString("username")); item.put("status",r.getString("status")); item.put("session_id",r.getObject("session_id") == null ? 0 : r.getInt("session_id")); item.put("selfie_path",r.getString("selfie_path") == null ? "" : r.getString("selfie_path")); item.put("location_verified",r.getInt("location_verified") == 1); item.put("recorded_at",r.getString("recorded_at")); item.put("course_code",r.getString("course_code") == null ? "" : r.getString("course_code")); item.put("course_name",r.getString("course_name") == null ? "" : r.getString("course_name")); item.put("date",r.getString("date") == null ? "" : r.getString("date")); item.put("time",r.getString("time") == null ? "" : r.getString("time")); activity.add(item);}} out.put("users",users); out.put("activity",activity); out.put("students",users.stream().filter(u -> "student".equals(u.get("role"))).count()); out.put("lecturers",users.stream().filter(u -> "lecturer".equals(u.get("role"))).count()); out.put("courses",count(c,"courses")); out.put("sessions",count(c,"attendance_sessions")); out.put("attendance",count(c,"attendance"));}
    respond(e,200,out); }
  static int count(Connection c,String table)throws SQLException{try(ResultSet r=c.createStatement().executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getInt(1);}}
  static void seedDefaultCourses(Connection c)throws SQLException{String[][] defaults={{"BSC-CS","BSc. Computer Science"},{"BSC-BIT","BSc. Business Information Technology"},{"BSC-BA","BSc. Business Administration"}}; try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO courses(course_code,course_name,lecturer_id) SELECT ? || '-' || id,?,id FROM users WHERE role='lecturer' AND NOT EXISTS (SELECT 1 FROM courses WHERE course_name=? AND lecturer_id=users.id)")){for(String[] item:defaults){p.setString(1,item[0]);p.setString(2,item[1]);p.setString(3,item[1]);p.addBatch();}p.executeBatch();}}
  static void createCourse(HttpExchange e, JsonNode b) throws Exception { int lecturerId=b.has("lecturer_id")?b.get("lecturer_id").asInt(-1):-1; String code=text(b,"course_code"), name=text(b,"course_name"); if(lecturerId<1||code.isBlank()||name.isBlank()){respond(e,400,Map.of("error","lecturer_id, course_code, and course_name are required."));return;} try(Connection c=db()){if(!isLecturer(c,lecturerId)){respond(e,403,Map.of("error","Only lecturers can create courses."));return;}try(PreparedStatement p=c.prepareStatement("INSERT INTO courses(course_code,course_name,lecturer_id) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,code);p.setString(2,name);p.setInt(3,lecturerId);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();respond(e,201,Map.of("message","Course created.","course",Map.of("id",k.getInt(1),"course_code",code,"course_name",name,"lecturer_id",lecturerId)));}}}catch(SQLException x){respond(e,x.getErrorCode()==19?409:500,Map.of("error",x.getErrorCode()==19?"Course code already exists.":"Could not create course."));}}
  static void createSession(HttpExchange e, JsonNode b) throws Exception { int lecturerId=b.has("lecturer_id")?b.get("lecturer_id").asInt(-1):-1, courseId=b.has("course_id")?b.get("course_id").asInt(-1):-1; String date=text(b,"date"), time=text(b,"time"); if(lecturerId<1||courseId<1||date.isBlank()||time.isBlank()){respond(e,400,Map.of("error","lecturer_id, course_id, date, and time are required."));return;}try(Connection c=db()){if(!isLecturer(c,lecturerId)){respond(e,403,Map.of("error","Only lecturers can create sessions."));return;}String courseName;try(PreparedStatement q=c.prepareStatement("SELECT course_name FROM courses WHERE id=? AND lecturer_id=?")){q.setInt(1,courseId);q.setInt(2,lecturerId);try(ResultSet r=q.executeQuery()){if(!r.next()){respond(e,404,Map.of("error","Course not found for this lecturer."));return;}courseName=r.getString(1);}}String token=token(courseId,courseName,date,time);try(PreparedStatement p=c.prepareStatement("INSERT INTO attendance_sessions(course_id,\"date\",\"time\",token) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,courseId);p.setString(2,date);p.setString(3,time);p.setString(4,token);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();respond(e,201,Map.of("message","Attendance session created.","session",Map.of("id",k.getInt(1),"course_id",courseId,"course_name",courseName,"date",date,"time",time,"token",token)));}}}catch(SQLException x){respond(e,500,Map.of("error","Could not create attendance session."));}}
  static void scanAttendance(HttpExchange e, JsonNode b) throws Exception { int userId=b.has("user_id")?b.get("user_id").asInt(-1):-1; String token=text(b,"token"), selfie=text(b,"selfie_data"); double lat=b.has("latitude")?b.get("latitude").asDouble(Double.NaN):Double.NaN, lon=b.has("longitude")?b.get("longitude").asDouble(Double.NaN):Double.NaN; if(userId<1||token.isBlank()||selfie.isBlank()||Double.isNaN(lat)||Double.isNaN(lon)){respond(e,400,Map.of("error","token, user_id, selfie_data, latitude, and longitude are required."));return;}try(Connection c=db()){if(!studentExists(c,userId)){respond(e,403,Map.of("error","Only registered students can scan attendance."));return;}int sessionId;try(PreparedStatement q=c.prepareStatement("SELECT id FROM attendance_sessions WHERE token=?")){q.setString(1,token);try(ResultSet r=q.executeQuery()){if(!r.next()){respond(e,404,Map.of("error","Invalid or expired QR token."));return;}sessionId=r.getInt(1);}}try(PreparedStatement q=c.prepareStatement("SELECT id FROM attendance WHERE user_id=? AND session_id=?")){q.setInt(1,userId);q.setInt(2,sessionId);if(q.executeQuery().next()){respond(e,409,Map.of("error","Attendance already recorded for this session."));return;}}if(!insidePalmCampus(lat,lon)){respond(e,403,Map.of("error","You must be within Palm University College to record attendance."));return;}String path=saveSelfie(selfie,userId);try(PreparedStatement p=c.prepareStatement("INSERT INTO attendance(user_id,status,session_id,selfie_path,location_verified) VALUES(?,?,?,?,1)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,userId);p.setString(2,"Present");p.setInt(3,sessionId);p.setString(4,path);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();respond(e,201,Map.of("message","Attendance recorded securely.","attendanceId",k.getInt(1),"session_id",sessionId,"selfie_path",path,"location_verified",true));}}}catch(IllegalArgumentException x){respond(e,400,Map.of("error","Selfie data must be a valid image."));}}
  static boolean isLecturer(Connection c,int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT id FROM users WHERE id=? AND role='lecturer'")){p.setInt(1,id);return p.executeQuery().next();}}
  static boolean studentExists(Connection c,int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT id FROM users WHERE id=? AND role='student'")){p.setInt(1,id);return p.executeQuery().next();}}
  static String token(int courseId,String name,String date,String time)throws Exception{Map<String,Object> payload=Map.of("course_id",courseId,"course_name",name,"date",date,"time",time,"nonce",UUID.randomUUID().toString());return Base64.getUrlEncoder().withoutPadding().encodeToString(JSON.writeValueAsBytes(payload));}
  static String saveSelfie(String data,int userId)throws IOException{String raw=data.contains(",")?data.substring(data.indexOf(',')+1):data;byte[] bytes=Base64.getDecoder().decode(raw);Path dir=Paths.get("uploads","selfies");Files.createDirectories(dir);String file="selfie-"+userId+"-"+UUID.randomUUID()+".jpg";Files.write(dir.resolve(file),bytes,StandardOpenOption.CREATE_NEW);return dir.resolve(file).toString().replace('\\','/');}
  // Palm University College is in Manya Jorpanya, Shai Hills, Greater Accra. Keep the radius configurable for survey-verified boundaries.
  static boolean insidePalmCampus(double lat,double lon){double campusLat=5.8065, campusLon=0.1415, radiusMeters=750;double dLat=Math.toRadians(lat-campusLat),dLon=Math.toRadians(lon-campusLon);double a=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(Math.toRadians(campusLat))*Math.cos(Math.toRadians(lat))*Math.sin(dLon/2)*Math.sin(dLon/2);return 6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))<=radiusMeters;}
  static void addColumnIfMissing(Connection c,String table,String column,String definition)throws SQLException{try(ResultSet r=c.getMetaData().getColumns(null,null,table,column)){if(!r.next())c.createStatement().executeUpdate("ALTER TABLE "+table+" ADD COLUMN "+column+" "+definition);}}
  static Map<String,Object> user(int id,String name,String email,String role){return Map.of("id",id,"username",name,"email",email,"role",role);}
  static String hash(String value) throws Exception { byte[] salt=new byte[16];SecureRandom.getInstanceStrong().nextBytes(salt);byte[] key=derive(value.toCharArray(),salt);return Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(key); }
  static boolean verify(String value,String stored) throws Exception {String[] p=stored.split(":");return p.length==2&&MessageDigest.isEqual(derive(value.toCharArray(),Base64.getDecoder().decode(p[0])),Base64.getDecoder().decode(p[1]));}
  static byte[] derive(char[] value,byte[] salt)throws Exception{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(value,salt,120000,256)).getEncoded();}
  static void respond(HttpExchange e,int code,Object body)throws IOException{byte[] out=JSON.writeValueAsBytes(body);e.getResponseHeaders().set("Content-Type","application/json");e.getResponseHeaders().set("Access-Control-Allow-Origin","*");e.sendResponseHeaders(code,out.length);try(OutputStream s=e.getResponseBody()){s.write(out);}}
}
